import { useLayoutEffect, useRef, useState, type ReactNode } from "react";
import { RefreshCw } from "lucide-react";
import { PrismFileTextGlyph as FileText } from "./prism-icon";
import { PrismTooltip } from "./prism-utility";
import { PrismButton } from "./prism-button";

export function PrismAdminLayout({ title, description, actions, filters, toolbar, children, pagination }: {
    title: string; description?: string; actions?: ReactNode; filters?: ReactNode; toolbar?: ReactNode; children: ReactNode; pagination?: ReactNode;
}) {
    return <section className="prism-admin"><header className="prism-admin-header"><div><h1>{title}</h1>{description && <p>{description}</p>}</div>{actions}</header>
        <div className="prism-admin-body">{filters && <div className="prism-admin-filters">{filters}</div>}{toolbar && <div className="prism-admin-toolbar">{toolbar}</div>}
            <div className="prism-admin-content">{children}</div>{pagination}</div></section>;
}
export type PrismAttachment = { id: string; name: string; href?: string; sizeLabel?: string; status?: "ready" | "uploading" | "error"; error?: string };
export function PrismAttachmentList({ files, onRemove, onDownload }: { files: readonly PrismAttachment[]; onRemove?: (id: string) => void; onDownload?: (file: PrismAttachment) => void }) {
    return <ul className="prism-attachments">{files.length ? files.map(file => <li key={file.id}><FileText aria-hidden="true" /><div>
        {file.href && /^(https?:\/\/|\/[^/])/.test(file.href) ? <a href={file.href} download>{file.name}</a> : onDownload ? <button type="button" onClick={() => onDownload(file)}>{file.name}</button> : <span>{file.name}</span>}
        {file.sizeLabel && <small>{file.sizeLabel}</small>}{file.status === "uploading" && <span role="status">업로드 중</span>}{file.status === "error" && <p role="alert" className="prism-error">{file.error ?? "첨부하지 못했습니다."}</p>}</div>
        {onRemove && <PrismButton variant="shape" size="small" aria-label={`${file.name} 제거`} onClick={() => onRemove(file.id)}>제거</PrismButton>}</li>) : <li className="prism-help">첨부파일이 없습니다.</li>}</ul>;
}
export function PrismSyncStatus({ status, updatedAt, onRefresh }: { status: "idle" | "syncing" | "error"; updatedAt?: string; onRefresh?: () => void }) {
    return <div className="prism-sync-status"><span role={status === "error" ? "alert" : "status"}>{status === "syncing" ? "동기화 중입니다." : status === "error" ? "동기화에 실패했습니다." : `최근 갱신: ${updatedAt ?? "기록 없음"}`}</span>
        {onRefresh && <PrismButton variant="shape" size="small" icon={<RefreshCw />} disabled={status === "syncing"} onClick={onRefresh}>새로고침</PrismButton>}</div>;
}
export function PrismTruncatedText({ text, maxLength = 60 }: { text: string; maxLength?: number }) {
    const ref=useRef<HTMLSpanElement>(null); const [truncated,setTruncated]=useState(false);
    useLayoutEffect(() => {const node=ref.current;if(!node)return;const measure=()=>setTruncated(node.scrollWidth>node.clientWidth);measure();const observer=new ResizeObserver(measure);observer.observe(node);return ()=>observer.disconnect();},[text,maxLength]);
    const content=<span ref={ref} className="prism-truncated" style={{maxWidth:`${maxLength}ch`}} tabIndex={truncated ? 0 : undefined}>{text}</span>;
    return truncated ? <PrismTooltip content={text}>{content}</PrismTooltip> : content;
}

import type { ReactNode } from "react";
import { PrismCheckGlyph as Check, PrismStarGlyph as Star } from "./prism-icon";
import { PrismOutline, PrismCompetenceMatrix } from "./prism-profile";
import { PrismChip } from "./prism-badge";
import { PrismRadarChart } from "./prism-chart";

export function PrismAssessmentSummary({ title = "SUMMARY", heading, description }: { title?: string; heading?: string | null; description?: string | null }) {
    return <PrismOutline title={title}><div className="prism-assessment-summary">{heading || description ? <>{heading && <strong>{heading}</strong>}{description && <p>{description}</p>}</> : <PrismNoData />}</div></PrismOutline>;
}
export function PrismNoData({ message = "관련 데이터 없음" }: { message?: string }) { return <p className="prism-no-data">{message}</p>; }
export type PrismRiskItem = { id: string; label: string; latent: boolean | null; manifest: boolean | null };
export function PrismRiskTable({ items }: { items: readonly PrismRiskItem[] }) {
    const merged = { latent: items.length > 0 && items.every(i => i.latent === null), manifest: items.length > 0 && items.every(i => i.manifest === null) };
    return <section className="prism-risk"><h3>Derailment Risk</h3><div className="prism-assessment-table-scroll"><table><caption className="prism-sr-only">잠재·발현 Risk</caption>
        <thead><tr><th scope="col">항목</th><th scope="col">잠재 Risk<small>성격가치검사</small></th><th scope="col">발현 Risk<small>6Frame Survey 결과</small></th></tr></thead>
        <tbody>{items.length ? items.map((item,index) => <tr key={item.id}><th scope="row">{item.label}</th>{(["latent","manifest"] as const).map(key => merged[key] ? index === 0 && <td key={key} rowSpan={items.length}>관련 데이터 없음</td> :
            <td key={key}>{item[key] === null ? "관련 데이터 없음" : item[key] ? <><Check aria-hidden="true" /><span className="prism-sr-only">해당</span></> : <span aria-label="해당 없음">-</span>}</td>)}</tr>) : <tr><td colSpan={3}>관련 데이터 없음</td></tr>}</tbody></table></div></section>;
}
export function PrismValueShares({ items }: { items: readonly { label: string; percent: number }[] }) {
    const colors = ["#2F548C","#2E8ED9","#98D0F5","#D7DCE3"];
    if (items.some(i => !Number.isFinite(i.percent) || i.percent < 0 || i.percent > 100) || items.reduce((sum,i) => sum+i.percent,0) > 100.01) throw new RangeError("Value shares must be 0..100 and total at most 100.");
    if (!items.some(i => i.percent > 0)) return <PrismNoData />;
    return <div className="prism-value-shares"><div className="prism-share-bar" aria-hidden="true">{items.map((item,i) => <span key={item.label} style={{width:`${item.percent}%`,background:colors[i%4]}} />)}</div>
        <ul>{items.map((item,i) => <li key={item.label}><span aria-hidden="true" style={{background:colors[i%4]}} />{item.label} <b>{item.percent}%</b></li>)}</ul></div>;
}
export function PrismDiagnosis({ title, axes, values, heading, description, shares, valueDescription, max = 10 }: { title: string; axes: readonly string[]; values: readonly (number | null)[];
    heading?: string; description?: string; shares?: readonly { label: string; percent: number }[]; valueDescription?: string; max?: number }) {
    return <PrismOutline title={title}><div className="prism-diagnosis"><section><header><strong>성격</strong><span>Big 5 기반 · {max}점 만점</span></header><div className="prism-diagnosis-row"><PrismRadarChart title="성격 진단" axes={axes.map((label,index) => ({id:String(index),label}))} series={[{id:"personality",label:"성격",values}]} max={max} /><div>{heading && <strong>{heading}</strong>}{description ? <p>{description}</p> : <PrismNoData />}</div></div></section>
        {shares && <section><header><strong>가치관</strong><span>가치 지향 비중 · %</span></header><PrismValueShares items={shares} />{valueDescription ? <p>{valueDescription}</p> : <PrismNoData />}</section>}</div></PrismOutline>;
}
export function PrismScoreEssay({ title, items }: { title: string; items: readonly { id: string; name: string; score: number | null; max: number; description: string | null }[] }) {
    if (items.some(i => !Number.isFinite(i.max) || i.max <= 0 || (i.score !== null && (!Number.isFinite(i.score) || i.score < 0 || i.score > i.max)))) throw new RangeError("Essay score must be null or 0..max.");
    return <PrismOutline title={title}><div className="prism-score-essays">{items.length ? items.map(item => <article key={item.id}><header><span>{item.name}</span><strong>{item.score ?? "--"}<small> / {item.max}</small></strong></header><p>{item.description ?? "관련 데이터 없음"}</p></article>) : <PrismNoData />}</div></PrismOutline>;
}
export function PrismExpertiseCards({ items }: { items: readonly { id: string; field: string; years: string; title?: string; description?: string }[] }) {
    return <PrismOutline title="전문 분야 및 대표 업적"><div className="prism-expertise-cards">{items.length ? items.map(item => <article key={item.id}><header><strong>{item.field}</strong><PrismChip>{item.years}</PrismChip></header><div>{item.title && <strong>{item.title}</strong>}{item.description ? <p>{item.description}</p> : <PrismNoData message="해당 내용 미작성" />}</div></article>) : <PrismNoData message="해당 내용 미작성" />}</div></PrismOutline>;
}
export function PrismExperienceTopics({ topics, value, onValueChange }: { topics: readonly { id: string; label: string; starred?: boolean }[]; value: string; onValueChange: (value: string) => void }) {
    return <div className="prism-experience-topics" role="group" aria-label="경험 영역">{topics.map(topic => <button type="button" key={topic.id} aria-pressed={value === topic.id} onClick={() => onValueChange(topic.id)}>{topic.starred && <Star fill="currentColor" aria-hidden="true" />}{topic.label}</button>)}</div>;
}
export function PrismExperienceEvidence({ title, items }: { title: string; items: readonly { id: string; label: string; hasExperience: boolean | null; description?: string }[] }) {
    return <PrismOutline title={title}><div className="prism-experience-evidence">{items.map(item => <article key={item.id}><header><strong>{item.label}</strong><PrismChip tone={item.hasExperience ? "primary" : "warning"}>{item.hasExperience === null ? "정보 없음" : item.hasExperience ? "작성내용 있음" : "작성내용 없음"}</PrismChip></header>{item.description && item.hasExperience ? <p>{item.description}</p> : <PrismNoData />}</article>)}</div></PrismOutline>;
}
export function PrismLeadershipReasons({ title, danger, items, comment }: { title: string; danger?: boolean; items: readonly { id: string; role: string; text: string | null }[]; comment?: string }) {
    return <PrismOutline title={title}><div className="prism-leadership-reasons" data-danger={danger || undefined}><dl>{items.map(item => <div key={item.id}><dt>{item.role}</dt><dd>{item.text ?? "관련 데이터 없음"}</dd></div>)}</dl>{comment && <aside><strong>요약</strong><p>{comment}</p></aside>}</div></PrismOutline>;
}
export function PrismDesignDiversity({ summary, columns, rows }: { summary: readonly { label: string; values: readonly string[] }[]; columns: readonly string[]; rows: readonly { id: string; label: string; values: readonly (string | null)[] }[] }) {
    return <PrismOutline title="다양성 Matrix"><div className="prism-diversity-summary">{summary.map(item => <div key={item.label}><strong>{item.label}</strong><div>{item.values.length ? item.values.map(value => <PrismChip key={value}>{value}</PrismChip>) : <PrismNoData />}</div></div>)}</div><PrismCompetenceMatrix columns={columns} rows={rows} /></PrismOutline>;
}
export function PrismProfileSections({ children }: { children: ReactNode }) { return <div className="prism-profile-sections">{children}</div>; }
export function PrismPositionMatrix({ columns, rows, rowAxisLabel, current }: { columns: readonly { id: string; label: string }[]; rows: readonly { id: string; label: string }[]; rowAxisLabel: string; current?: { row: string; column: string } | null }) {
    return <div className="prism-position-matrix" role="region" aria-label="다양성 Matrix" tabIndex={0}><table><caption className="prism-sr-only">다양성 Matrix · 현재 위치</caption><thead><tr><th scope="col">{rowAxisLabel}</th>{columns.map(column => <th scope="col" key={column.id}>{column.label}</th>)}</tr></thead>
        <tbody>{rows.map(row => <tr key={row.id}><th scope="row">{rowAxisLabel} {row.label}</th>{columns.map(column => { const selected = current?.row === row.id && current?.column === column.id; return <td data-current={selected || undefined} key={column.id}>{selected ? "현재 위치" : <span className="prism-sr-only">해당 없음</span>}</td>; })}</tr>)}</tbody></table></div>;
}
export function PrismProfileAnalysis({ leader, factors }: { leader?: { label: string; description?: string }; factors: readonly { id: string; label: string; title?: string; results: readonly string[]; summary?: string | null; starred?: readonly string[] }[] }) {
    return <div className="prism-profile-analysis">{leader && <div className="prism-analysis-leader"><strong>{leader.label}</strong><p>{leader.description ?? "관련 데이터 없음"}</p></div>}{factors.map(factor => <section key={factor.id}><h4>{factor.label}</h4><div>{factor.title && <strong>{factor.title}</strong>}<div>{factor.results.map(result => <PrismChip key={result}>{factor.starred?.includes(result) && <Star size={14} aria-hidden="true" />}{result}</PrismChip>)}</div><p>{factor.summary ?? "관련 데이터 없음"}</p></div></section>)}</div>;
}

import type { ComponentProps, CSSProperties, ReactNode } from "react";
import { PrismXGlyph as X } from "./prism-icon";

export function PrismElpBadge({ type, className = "", ...props }: ComponentProps<"span"> & { type: "ELP" | "s-ELP" }) {
    return <span {...props} className={`prism-elp ${className}`} data-type={type}>{type}</span>;
}
export function PrismCountBadge({ count, max = 99, children, showZero = false }: { count: number; max?: number; children?: ReactNode; showZero?: boolean }) {
    if (!Number.isSafeInteger(count) || count < 0 || !Number.isSafeInteger(max) || max < 1) throw new RangeError("Count must be a nonnegative integer and max a positive integer.");
    const badge = count || showZero ? <span className="prism-count" aria-label={`${count}건`}>{count > max ? `${max}+` : count}</span> : null;
    return children ? <span className="prism-count-anchor">{children}{badge}</span> : badge;
}
export function PrismTag({ children, variant = "gray", onRemove, label, className = "", ...props }: ComponentProps<"span"> & {
    variant?: "gray" | "blue" | "mainBlue"; onRemove?: () => void; label?: string;
}) {
    if (onRemove && !label) throw new Error("Removable PrismTag requires label.");
    return <span {...props} className={`prism-tag ${className}`} data-variant={variant}>{children}
        {onRemove && <button type="button" aria-label={`${label} 삭제`} onClick={onRemove}><X size={16} aria-hidden="true" /></button>}</span>;
}
export function PrismChip({ children, tone = "primary", color, variant = "soft", ...props }: ComponentProps<"span"> & {
    tone?: "primary" | "success" | "warning" | "danger"; color?: string; variant?: "soft" | "solid";
}) {
    return <span {...props} className={`prism-chip ${props.className ?? ""}`} data-variant={variant}
        style={{ "--chip-tone": color ?? `var(--${tone === "primary" ? "accent" : tone})`, ...props.style } as CSSProperties}>{children}</span>;
}

import type { ComponentProps, ReactNode } from "react";
import { Button } from "./button";

export type PrismButtonProps = Omit<ComponentProps<typeof Button>, "variant" | "size"> & {
    variant?: "solid" | "line" | "shape";
    size?: "large" | "medium" | "small" | "x-small";
    tone?: "neutral" | "primary" | "danger";
    icon?: ReactNode;
    iconOnly?: boolean;
    iconPosition?: "left" | "right";
};

/** HRXBtn 규격. Native button 동작과 ref는 pydemia Button에 위임합니다. */
export function PrismButton({ variant = "solid", size = "medium", tone = variant === "solid" ? "primary" : "neutral",
    icon, iconOnly, iconPosition = "left", children, className = "", ...props }: PrismButtonProps) {
    if (iconOnly && !props["aria-label"] && !props["aria-labelledby"]) {
        throw new Error("PrismButton iconOnly requires an accessible name.");
    }
    return <Button {...props} variant={variant === "solid" ? "primary" : variant === "line" ? "outline" : "ghost"}
        className={`prism-button ${className}`} data-size={size} data-variant={variant}
        data-tone={tone} data-icon-only={iconOnly || undefined} data-icon-position={iconPosition}>
        {icon && <span className="prism-button-icon" aria-hidden="true">{icon}</span>}
        {!iconOnly && children}
    </Button>;
}

export function PrismNewChatButton(props: Omit<PrismButtonProps, "variant" | "size">) {
    return <PrismButton {...props} size="large" className={`prism-new-chat ${props.className ?? ""}`} />;
}

import { useId, type ReactNode } from "react";
import { PrismIcon } from "./prism-icon";
import { PrismElpBadge, PrismChip } from "./prism-badge";
import { PrismTable } from "./prism-display";
import { PrismFavoriteToggle, PrismAffiliateLogo } from "./prism-primitives";
import { PrismEvaluationHistory } from "./prism-record";

export type PrismCandidate = { id: string; name: string; company: string; position: string; executiveYears?: number;
    elp?: "ELP" | "s-ELP"; photo?: string; speciality?: string; summary?: string;
    birthDate?: string; appointmentDate?: string; groupJoinDate?: string; education?: string;
    brand?: string; companyField?: string; domain?: string; presidentPromotionDate?: string; groupJoinYears?: number;
    recentEvaluations?: readonly {year:string;grade:string|null;active?:boolean}[]; compensationText?: string | null };
export type PrismCandidateCardProps = { candidate: PrismCandidate; rank?: number; selected?: boolean; favorite?: boolean;
    onOpen: (candidate: PrismCandidate) => void; onFavoriteChange?: (value: boolean) => void; children?: ReactNode;
    variant?: "stack" | "pair" | "grid"; panel?: boolean; showDetails?: boolean };
export function PrismCandidateCard({ candidate, rank, selected, favorite, onOpen, onFavoriteChange, children, variant = "stack", panel, showDetails }: PrismCandidateCardProps) {
    const nameId=useId();
    return <article className="prism-candidate-card" data-selected={selected || undefined} data-variant={variant} data-panel={panel || undefined}>
        <button type="button" className="prism-candidate-open" aria-labelledby={nameId} onClick={()=>onOpen(candidate)}/>
        {rank !== undefined && <span className="prism-rank">{rank}순위</span>}
        <div className="prism-candidate-header"><div className="prism-candidate-photo" aria-hidden="true">
            {candidate.photo && <img src={candidate.photo} alt="" />}</div>
            <div className="prism-candidate-info"><div className="prism-candidate-name"><span id={nameId} className="prism-candidate-label">{candidate.name}</span>
                {candidate.elp && <PrismElpBadge type={candidate.elp} />}</div><div className="prism-candidate-categories">{candidate.companyField&&<b>{candidate.companyField}</b>}{(candidate.domain??candidate.speciality)&&<span>{candidate.domain??candidate.speciality}</span>}</div><p><PrismAffiliateLogo brand={candidate.brand} affiliate={candidate.company} size={12}/></p><p>{candidate.position}</p></div>
            {onFavoriteChange && <PrismFavoriteToggle name={candidate.name} checked={!!favorite} onCheckedChange={onFavoriteChange}/>}</div>
        <PrismCandidateBrief candidate={candidate} compact={variant==="grid"} single={variant==="stack"&&!panel}/>
        {candidate.summary && <p className="prism-candidate-summary">{candidate.summary}</p>}{children&&<div className="prism-candidate-extra">{children}</div>}
        {(showDetails??(variant==="stack"&&!panel)) && <button type="button" className="prism-candidate-detail-button" onClick={() => onOpen(candidate)}>상세 프로필 보기<PrismIcon name="ChevronRightIcon" size={16}/></button>}</article>;
}
/** Values are prepared by the consumer; no currency conversion or evaluation rules run here. */
export function PrismCandidateBrief({candidate,compact=false,single=true}:{candidate:PrismCandidate;compact?:boolean;single?:boolean}) {
    const fields:readonly [string,ReactNode][]=[["생년월일",candidate.birthDate??"-"],["임원 선임일",candidate.appointmentDate ? `${candidate.appointmentDate}${candidate.executiveYears===undefined ? "" : ` (${candidate.executiveYears}년차)`}` : "-"],
        ...(candidate.presidentPromotionDate?.trim() ? [["사장 승진일",candidate.presidentPromotionDate] as [string,ReactNode]] : []),["그룹 입사일",candidate.groupJoinDate ? `${candidate.groupJoinDate}${candidate.groupJoinYears===undefined ? "" : ` (${candidate.groupJoinYears}년차)`}` : "-"],...(!compact ? [["최종 학위",candidate.education??"-"] as [string,ReactNode]] : [])];
    return <dl className="prism-candidate-brief">{fields.map(([label,value])=><div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}
        {!compact&&<><div><dt>최근 평가 이력</dt><dd><PrismEvaluationHistory items={candidate.recentEvaluations??[]}/></dd></div>{single&&<><hr/><div><dt>최근 보상 정보<small>단위 : 백만원</small></dt><dd>{candidate.compensationText??"-"}</dd></div></>}</>}</dl>;
}
export function PrismCandidateTable({ candidates, onOpen, caption = "후보자 목록" }: { candidates: readonly PrismCandidate[];
    onOpen: (candidate: PrismCandidate) => void; caption?: string }) {
    return <PrismTable caption={caption}><thead><tr><th scope="col">이름 (임원 경력 / ELP)</th><th scope="col">회사명 / 현재 직책</th></tr></thead>
        <tbody>{candidates.length ? candidates.map(candidate => <tr key={candidate.id}><td><div className="prism-candidate-cell">
            <button type="button" onClick={() => onOpen(candidate)}>{candidate.name}</button>
            {candidate.executiveYears !== undefined && <PrismChip>임원 {candidate.executiveYears}년차</PrismChip>}
            {candidate.elp && <PrismElpBadge type={candidate.elp} />}</div></td><td>{candidate.company} / {candidate.position}</td></tr>)
            : <tr><td colSpan={2}>표시할 후보자가 없습니다.</td></tr>}</tbody></PrismTable>;
}
export type PrismAssessment = { id: string; area: string; score: number | null; evidence: string };
export function PrismEvaluationTable({ assessments, caption = "적합성 평가" }: { assessments: readonly PrismAssessment[]; caption?: string }) {
    for (const item of assessments) if (item.score !== null && (!Number.isFinite(item.score) || item.score < 0 || item.score > 5)) throw new RangeError("Assessment score must be null or within 0–5.");
    return <PrismTable caption={caption}><thead><tr><th scope="col">평가 영역</th><th scope="col">평가 점수</th><th scope="col">판단 근거</th></tr></thead>
        <tbody>{assessments.map(item => <tr key={item.id}><th scope="row">{item.area}</th><td><PrismChip tone={item.score === null ? "warning" : "primary"}>
            {item.score === null ? "근거 부족" : `${item.score} / 5`}</PrismChip></td><td>{item.evidence}</td></tr>)}</tbody></PrismTable>;
}

import { useEffect, useId, useRef, useState } from "react";
export type PrismChartAxis = { id: string; label: string; description?: string };
export type PrismChartSeries = { id: string; label: string; values: readonly (number | null)[]; color?: string };
export type PrismLeadershipPieItem = { label: string; value: number | null };
export type PrismLeadershipPieProps = {
    title: string; items: readonly PrismLeadershipPieItem[]; size?: number; labelFontSize?: number; animate?: boolean;
};
const leadershipColors = ["#706ee7", "#55c4ae", "#ff928a"];
const turn = Math.PI * 2;
function pieSector(cx: number, cy: number, radius: number, start: number, end: number) {
    const point = (angle: number) => `${cx+Math.cos(angle)*radius},${cy+Math.sin(angle)*radius}`;
    if (end-start >= turn-1e-6) return `M ${point(start)} A ${radius},${radius} 0 1 1 ${point(start+Math.PI)} A ${radius},${radius} 0 1 1 ${point(end)} Z`;
    return `M ${cx},${cy} L ${point(start)} A ${radius},${radius} 0 ${end-start > Math.PI ? 1 : 0} 1 ${point(end)} Z`;
}
/** Percentages are supplied by the host; the unassigned sector is never an assessment value. */
export function PrismLeadershipPie({ title, items, size = 120, labelFontSize = 11, animate = true }: PrismLeadershipPieProps) {
    const id = useId(); const root = useRef<HTMLElement>(null);
    const [measured,setMeasured] = useState<readonly number[]>([]); const [available,setAvailable] = useState<number | null>(null);
    const [progress,setProgress] = useState(1);
    const signature = JSON.stringify(items); const total = items.reduce((sum,item) => sum+(item.value ?? 0),0);
    const complete = items.every(item => item.value !== null);
    if (!title.trim() || !items.length || items.length > 3 || new Set(items.map(item => item.label.trim())).size !== items.length || items.some(item => !item.label.trim())) throw new Error("Leadership pie requires a title and one to three unique labels.");
    if (!Number.isFinite(size) || size < 40 || size > 640 || !Number.isFinite(labelFontSize) || labelFontSize < 8 || labelFontSize > 24) throw new RangeError("Pie size must be 40..640 and label font size 8..24.");
