export function PrismBlankLayout({ gradient = true, children }: { gradient?: boolean; children: ReactNode }) { return <div className="prism-blank-layout" data-gradient={gradient || undefined}>{children}</div>; }
export function PrismErrorContent({ code, message, buttonLabel, onAction, icon }: { code?: string; message: string; buttonLabel: string; onAction: () => void; icon?: ReactNode }) {
    return <section className="prism-error-content" aria-label={code ? `오류 ${code}` : "접근 안내"}><div><div className="prism-error-illustration" aria-hidden="true">{icon ?? <PrismIcon name={code === "404" ? "NotFoundIcon" : code === "401" ? "UnauthorizedIcon" : "AccessDeniedIcon"} size={140} />}</div>{code && <p className="prism-error-code">{code}</p>}<p>{message}</p></div><PrismButton variant="line" onClick={onAction}>{buttonLabel}</PrismButton></section>;
}
export function PrismServiceContact({ label = "서비스 관련 문의", email }: { label?: string; email: string }) {
    return <div className="prism-service-contact"><span>{label}</span><span aria-hidden="true" />{email}</div>;
}
export function PrismAccessGate({ status, children, fallback }: { status:"ready" | "loading" | "denied"; children:ReactNode; fallback?:ReactNode }) {
    return status === "ready" ? children : status === "loading" ? <div className="prism-access-loading" role="status">접근 정보를 확인하는 중입니다.</div> : fallback;
}

import { useEffect, useId, useRef, useState, type CSSProperties, type ReactNode } from "react";
import { PrismMaximize2Glyph as Maximize2, PrismMinimize2Glyph as Minimize2, PrismXGlyph as X } from "./prism-icon";
import { PrismButton } from "./prism-button";

export type PrismPanelProps = {
    title: string; open: boolean; onOpenChange: (open: boolean) => void;
    expanded?: boolean; onExpandedChange?: (expanded: boolean) => void;
    children: ReactNode;
    resizable?: boolean; width?: number; defaultWidth?: number; minWidth?: number; maxWidth?: number;
    onWidthChange?: (width: number) => void; responsive?: boolean;
};
/** Render inside a position:relative flex container. The surrounding view stays usable. */
export function PrismPanel({ title, open, onOpenChange, expanded = false, onExpandedChange, children,
    resizable = false, width, defaultWidth = 440, minWidth = 320, maxWidth = 800, onWidthChange, responsive = true }: PrismPanelProps) {
    if([minWidth,maxWidth,defaultWidth,width??defaultWidth].some(value=>!Number.isFinite(value)||value<=0)||minWidth>maxWidth)throw new RangeError("Panel widths must be positive with minWidth <= maxWidth.");
    const id = useId();const panel=useRef<HTMLElement>(null);const [internalWidth,setInternalWidth]=useState(defaultWidth);const [containerWidth,setContainerWidth]=useState<number|null>(null);
    const drag=useRef<{pointerId:number;x:number;width:number}|null>(null);
    useEffect(()=>{const parent=panel.current?.parentElement;if(!parent)return;const measure=()=>{const next=parent.getBoundingClientRect().width;if(next>0)setContainerWidth(next);};measure();const observer=new ResizeObserver(measure);observer.observe(parent);return()=>observer.disconnect();},[]);
    const compact=responsive&&containerWidth!==null&&containerWidth<640;const upper=Math.min(maxWidth,containerWidth??maxWidth);const lower=Math.min(minWidth,upper);
    const currentWidth=Math.max(lower,Math.min(upper,width??internalWidth));
    const changeWidth=(next:number)=>{const clamped=Math.round(Math.max(lower,Math.min(upper,next)));if(width===undefined)setInternalWidth(clamped);if(clamped!==currentWidth)onWidthChange?.(clamped);};
    const style={"--prism-panel-width":`${currentWidth}px`} as CSSProperties;
    const close = () => { onExpandedChange?.(false); onOpenChange(false); };
    return <><div className="prism-panel-placeholder" style={style} data-open={open || undefined} data-compact={compact||undefined} aria-hidden="true" />
        <aside ref={panel} id={`${id}-panel`} style={style} className="prism-panel" hidden={!open} aria-labelledby={id} data-expanded={expanded || undefined} data-compact={compact||undefined}
            onKeyDown={e => { if (e.key === "Escape" && !e.defaultPrevented) { e.stopPropagation(); close(); } }}>
            {resizable&&!expanded&&!compact&&<div className="prism-panel-resizer" role="separator" aria-label={`${title} 패널 너비`} aria-controls={`${id}-panel`} aria-orientation="vertical" aria-valuemin={lower} aria-valuemax={upper} aria-valuenow={currentWidth} aria-valuetext={`${currentWidth}px`} tabIndex={0}
                onPointerDown={e=>{if(e.button!==0)return;e.preventDefault();e.currentTarget.focus();e.currentTarget.setPointerCapture(e.pointerId);drag.current={pointerId:e.pointerId,x:e.clientX,width:currentWidth};}}
                onPointerMove={e=>{if(drag.current?.pointerId===e.pointerId)changeWidth(drag.current.width+drag.current.x-e.clientX);}}
                onPointerUp={e=>{if(drag.current?.pointerId!==e.pointerId)return;drag.current=null;e.currentTarget.releasePointerCapture(e.pointerId);}}
                onPointerCancel={()=>{if(drag.current)changeWidth(drag.current.width);drag.current=null;}}
                onLostPointerCapture={()=>{drag.current=null;}} onDoubleClick={()=>changeWidth(defaultWidth)}
                onKeyDown={e=>{const step=e.shiftKey ? 50 : 16;const next=e.key==="ArrowLeft" ? currentWidth+step : e.key==="ArrowRight" ? currentWidth-step : e.key==="Home" ? lower : e.key==="End" ? upper : undefined;
                    if(next!==undefined){e.preventDefault();changeWidth(next);}if(e.key==="Escape"&&drag.current){e.preventDefault();changeWidth(drag.current.width);drag.current=null;}}}/>}
            <header><h2 id={id}>{title}</h2><div>{onExpandedChange && <PrismButton variant="shape" iconOnly
                aria-label={expanded ? "패널 축소" : "패널 확대"} icon={expanded ? <Minimize2 /> : <Maximize2 />}
                onClick={() => onExpandedChange(!expanded)} />}
                <PrismButton variant="shape" iconOnly aria-label="패널 닫기" icon={<X />} onClick={close} /></div></header>
            <div className="prism-panel-content">{children}</div>
        </aside></>;
}

import type { ReactNode } from "react";
import { PrismDetailList } from "./prism-detail";
import { PrismAffiliateLogo } from "./prism-primitives";
import { PrismRequestState } from "./prism-feedback";

export type PrismRequirementGroup = { id: string; title: string; items: readonly { id: string; title?: string; content: string | null }[] };
export function PrismPositionHeader({ company, brand, role, items }: { company: string; brand?: string; role: string; items: readonly { label: string; value: ReactNode }[] }) {
    return <header className="prism-position-header"><div><PrismAffiliateLogo brand={brand} affiliate={company} size={16} /><h2>{role}</h2></div><PrismDetailList items={items} /></header>;
}
export function PrismPositionRequirements({ group }: { group: PrismRequirementGroup }) {
    return <article className="prism-requirement"><header><h3>{group.title}</h3></header><div>{group.items.length ? group.items.map(item => <section key={item.id}>{item.title && <h4>{item.title}</h4>}<p>{item.content ?? "관련 데이터 없음"}</p></section>) : <p className="prism-no-data">관련 데이터 없음</p>}</div></article>;
}
export function PrismPositionDetail({ company, role, brand, items, groups, status = "ready", onRetry }: { company: string; role: string; brand?: string; items: readonly { label: string; value: ReactNode }[];
    groups: readonly PrismRequirementGroup[]; status?: "ready" | "loading" | "error"; onRetry?: () => void }) {
    if (status !== "ready") return <PrismRequestState status={status} onRetry={onRetry} />;
    return <div className="prism-position-detail"><PrismPositionHeader company={company} brand={brand} role={role} items={items} /><div>{groups.map(group => <PrismPositionRequirements key={group.id} group={group} />)}</div></div>;
}

import { useId, type CSSProperties, type ReactNode } from "react";
import { PrismIcon } from "./prism-icon";
import { PrismChevronDownGlyph as ChevronDown, PrismStarGlyph as Star } from "./prism-icon";
import { Popover, PopoverTrigger, PopoverContent } from "./popover";
import { PrismButton } from "./prism-button";
import { PrismInfoTooltip } from "./prism-utility";

export function PrismAffiliateLogo({ brand, affiliate, size = 48 }: { brand?: string; affiliate: string; size?: number | string }) {
    return <span className="prism-affiliate" style={{fontSize:size}}>{brand && <b>{brand}</b>}<span>{affiliate}</span></span>;
}
export function PrismSidebarProfile({ name, email, collapsed }: { name: string; email: string; collapsed?: boolean }) {
    return <div className="prism-sidebar-profile"><span aria-hidden="true">{name.trim().slice(0,1) || "?"}</span>{!collapsed && <div><strong>{name}</strong><small>{email}</small></div>}{collapsed && <span className="prism-sr-only">{name}</span>}</div>;
}
export type PrismInputLabelProps = {
    children: ReactNode; required?: boolean; htmlFor?: string; suffix?: ReactNode; tooltip?: string; tooltipLabel?: string;
    className?: string; style?: CSSProperties;
};
export function PrismInputLabel({ children, required, htmlFor, suffix, tooltip, tooltipLabel, className = "", style }: PrismInputLabelProps) {
    const text = <>{children}{required && <span className="prism-input-required" aria-hidden="true">*</span>}{required && <span className="prism-sr-only">필수</span>}{suffix}</>;
    if (!tooltip?.trim()) return <label className={`prism-input-label ${className}`} style={style} htmlFor={htmlFor}>{text}</label>;
    return <span className={`prism-input-label ${className}`} style={style}>
        <label className="prism-input-label-text" htmlFor={htmlFor}>{text}</label>
        <PrismInfoTooltip label={tooltipLabel ?? (typeof children === "string" ? `${children} 설명` : "입력 항목 설명")} content={tooltip}
            side="bottom" arrow={false} contentProps={{className:"prism-label-tooltip",sideOffset:14}}/>
    </span>;
}
export function PrismSkeleton({ width = "100%", height = 16, radius = 4 }: { width?: CSSProperties["width"]; height?: CSSProperties["height"]; radius?: number }) {
    return <span className="prism-skeleton" aria-hidden="true" style={{width,height,borderRadius:radius}} />;
}
export function PrismSkeletonGroup({ label = "불러오는 중", rows = 3, height = 120 }: { label?: string; rows?: number; height?: CSSProperties["height"] }) {
    return <div className="prism-skeleton-group" role="status" aria-label={label}>{Array.from({length:Math.max(1,Math.min(20,rows))},(_,i) => <PrismSkeleton key={i} width="100%" height={height} radius={8} />)}<span className="prism-sr-only">{label}</span></div>;
}
export function PrismPopover({ trigger, children, open, onOpenChange }: { trigger: ReactNode; children: ReactNode; open?: boolean; onOpenChange?: (open: boolean) => void }) {
    return <Popover open={open} onOpenChange={onOpenChange}><PopoverTrigger asChild>{trigger}</PopoverTrigger><PopoverContent data-prism="light" className="prism-popover">{children}</PopoverContent></Popover>;
}
export function PrismFavoriteToggle({ name, checked, onCheckedChange, disabled }: { name: string; checked: boolean; onCheckedChange: (checked: boolean) => void; disabled?: boolean }) {
    return <button type="button" className="prism-favorite-toggle" aria-label={`${name} 즐겨찾기`} aria-pressed={checked} disabled={disabled} onClick={() => onCheckedChange(!checked)}><Star aria-hidden="true" fill={checked ? "currentColor" : "none"} /></button>;
}
export function PrismShowMore({ expanded, hiddenCount, onExpandedChange, children, label = "더보기" }: { expanded: boolean; hiddenCount: number; onExpandedChange: (expanded: boolean) => void; children?: ReactNode; label?: string }) {
    const id = useId(); return <div className="prism-show-more">{children && <div id={id} hidden={!expanded}>{children}</div>}<PrismButton variant="line" size="large" aria-expanded={expanded} aria-controls={children ? id : undefined} icon={<ChevronDown style={{transform:expanded ? "rotate(180deg)" : undefined}} />} iconPosition="right" onClick={() => onExpandedChange(!expanded)}>{expanded ? "접기" : `${label} (${hiddenCount})`}</PrismButton></div>;
}
export function PrismFloatingChatButton({ onClick, right = 40, bottom = 40 }: { onClick: () => void; right?: CSSProperties["right"]; bottom?: CSSProperties["bottom"] }) {
