/* PRISM light profile. Values are measured from PRISM-DEV and source design tokens. */
[data-prism="light"] {
    --prism-base: #fdfdfd; --prism-lnb: #f9fafc; --prism-panel: #eef1f8;
    --prism-border: #e3e5e5; --prism-control-border: #d4d8dd; --prism-divider: #e7e9ed;
    --prism-primary: #2f548c; --prism-secondary: #fa7c39;
    --prism-cool-100: #eef2fa; --prism-cool-200: #d6dcee; --prism-cool-700: #384a7d; --prism-cool-800: #1f3365;
    --prism-neutral-50: #f4f5f8; --prism-neutral-100: #e7eaee; --prism-neutral-200: #d7dce3;
    --prism-caption: #9aa3af; --prism-sub: #868686;
    --prism-blue-300: #2e8ed9; --prism-blue-400: #0072c6; --prism-cool-300: #b8c2da;
    --background: var(--prism-base); --surface: var(--prism-base); --foreground: #222;
    --surface-subtle: var(--prism-neutral-50); --border: var(--prism-control-border);
    --accent: var(--prism-primary); --accent-foreground: #fff; --muted: #626a75;
    --focus: #2e8ed9; --danger: #ea002c; --success: #256645; --warning: #95620a;
    --message-user-background: var(--prism-cool-100); --message-user-foreground: #222;
    --radius: 6px; --control-height: 32px; --density-control-height: 32px;
    --font-ui: "Pretendard Variable", Pretendard, sans-serif; --overlay: rgb(0 0 0 / 40%);
    --shadow-float: 0 4px 24px rgb(37 38 46 / 16%);
    --shadow-medium: 0 4px 16px rgb(37 38 46 / 12%);
